async def open_socket(
    http: httpx2.AsyncClient,
    x: Exchange,
    headers: Mapping[str, str],
    protocols: Sequence[str],
) -> TypedWebSocket:
    scheme, sep, rest = x.url().partition("://")
    url = {"http": "ws", "https": "wss"}.get(scheme, scheme) + sep + rest
    key = base64.b64encode(os.urandom(16)).decode()
    offered = {"Sec-WebSocket-Protocol": ", ".join(protocols)} if protocols else {}
    sent = {**headers, **UPGRADE, "Sec-WebSocket-Key": key, **offered}
    loop = asyncio.get_running_loop()
    opened: asyncio.Future[AsyncWebSocketSession] = loop.create_future()
    done = asyncio.Event()

    async def hold() -> None:
        async with http.stream(
            "GET", url, headers=sent, follow_redirects=False, timeout=x.timeout
        ) as answer:
            raw = x.raw
            raw.status, raw.headers, raw.url = (
                answer.status_code,
                answer.headers,
                str(answer.url),
            )
            raw.body = b""
            if answer.status_code != 101:
                chunks: list[bytes] = []
                async for chunk in answer.aiter_bytes():
                    x.read(chunks, chunk)
                raw.body = b"".join(chunks)
                raise status_error(
                    answer.status_code, answer.headers, raw.body, x.core.keys
                )
            stream = answer.extensions["network_stream"]
            every = x.core.config.ws_keepalive or None
            async with AsyncWebSocketSession(
                stream,
                max_message_size_bytes=16 << 20,
                keepalive_ping_interval_seconds=every,
                keepalive_ping_timeout_seconds=every,
                response=answer,
            ) as session:
                opened.set_result(session)
                await done.wait()

    task = loop.create_task(hold())
    task.add_done_callback(lambda held: held.cancelled() or held.exception())
    try:
        both = asyncio.wait((opened, task), return_when=asyncio.FIRST_COMPLETED)
        await raced(both, x.options.get("cancel"))
        if not opened.done():
            raise task.exception() or APIConnectionError("the WebSocket ended")
    except BaseException as error:
        done.set()
        task.cancel()
        if isinstance(error, httpx2.TimeoutException):
            raise APITimeoutError("the call ran past its timeout") from error
        if isinstance(error, HoneyError) or not isinstance(error, Exception):
            raise
        raise APIConnectionError("the WebSocket handshake failed") from error
    return TypedWebSocket(opened.result(), done, task, x.options.get("cancel"))


